const input = $json.body ?? $json;
const now = new Date();
const clean = (value) => typeof value === 'string' ? value.trim() : value;
const employee = {
  employeeId: clean(input.employeeId),
  fullName: clean(input.fullName),
  personalEmail: clean(input.personalEmail),
  jobTitle: clean(input.jobTitle),
  department: clean(input.department),
  location: clean(input.location),
  country: clean(input.country ?? 'PK'),
  employmentType: clean(input.employmentType ?? 'FULL_TIME'),
  workMode: clean(input.workMode ?? 'HYBRID'),
  startDate: clean(input.startDate),
  managerId: clean(input.managerId)
};
const required = ['employeeId', 'fullName', 'personalEmail', 'jobTitle', 'department', 'location', 'startDate', 'managerId'];
const missingFields = required.filter((key) => !employee[key]);
const conflicts = [];
if (employee.personalEmail && !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(employee.personalEmail)) conflicts.push('INVALID_PERSONAL_EMAIL');
if (employee.startDate && !/^\d{4}-\d{2}-\d{2}$/.test(employee.startDate)) conflicts.push('INVALID_START_DATE_FORMAT');
const start = employee.startDate ? new Date(employee.startDate + 'T00:00:00Z') : null;
if (start && Number.isNaN(start.getTime())) conflicts.push('INVALID_START_DATE');
const safeEmployeeId = employee.employeeId || 'UNKNOWN';
const safeStartDate = employee.startDate || 'UNKNOWN';
const idempotencyKey = `${safeEmployeeId}:${safeStartDate}`;
let hash = 0;
for (const char of idempotencyKey) hash = ((hash << 5) - hash + char.charCodeAt(0)) | 0;
const caseId = `ONB-${now.getUTCFullYear()}-${String(Math.abs(hash)).padStart(8, '0').slice(0, 8)}`;
const requiresHumanReview = missingFields.length > 0 || conflicts.length > 0;
return [{ json: {
  schemaVersion: '1.0',
  workflowVersion: 'prototype-1.0',
  caseId,
  correlationId: input.correlationId ?? caseId,
  idempotencyKey,
  receivedAt: now.toISOString(),
  status: requiresHumanReview ? 'NEEDS_REVIEW' : 'APPROVED',
  employee,
  documents: Array.isArray(input.documents) ? input.documents.map((document) => ({ documentId: document.documentId, type: document.type ?? 'UNKNOWN', storageUri: document.storageUri, malwareScan: document.malwareScan ?? 'PENDING' })) : [],
  validation: { missingFields, conflicts, requiresHumanReview },
  requestedSystems: Array.isArray(input.requestedSystems) ? input.requestedSystems : [],
  audit: [{ event: 'INTAKE_VALIDATED', at: now.toISOString(), actor: 'workflow', result: requiresHumanReview ? 'REVIEW_REQUIRED' : 'PASSED' }]
} }];

const record = $json;
return [{ json: {
  accepted: false,
  caseId: record.caseId,
  status: 'NEEDS_REVIEW',
  reviewQueue: 'HR_OPERATIONS',
  reasonCodes: [...record.validation.missingFields.map((field) => `MISSING_${field.toUpperCase()}`), ...record.validation.conflicts],
  message: 'The onboarding case was quarantined for authorized HR review. No provisioning actions were created.',
  audit: [...record.audit, { event: 'ROUTED_TO_HUMAN_REVIEW', at: new Date().toISOString(), actor: 'workflow' }]
} }];

const record = $json;
const start = new Date(record.employee.startDate + 'T09:00:00Z');
const due = (offsetDays) => { const value = new Date(start); value.setUTCDate(value.getUTCDate() + offsetDays); return value.toISOString(); };
const roleKey = `${record.employee.department}:${record.employee.jobTitle}`.toLowerCase();
const equipmentProfile = roleKey.includes('engineering') || roleKey.includes('data') ? 'TECHNICAL_LAPTOP' : 'STANDARD_LAPTOP';
const baseline = [
  { taskCode: 'HR_DOCUMENTS', title: 'Verify required HR documents', ownerGroup: 'HR', dueOffset: -5, risk: 'STANDARD' },
  { taskCode: 'IT_DEVICE', title: `Prepare ${equipmentProfile.toLowerCase().replace('_', ' ')}`, ownerGroup: 'IT', dueOffset: -2, risk: 'STANDARD' },
  { taskCode: 'IDENTITY_ACCOUNT', title: 'Create identity and email account', ownerGroup: 'IT_IDENTITY', dueOffset: -1, risk: 'CONTROLLED' },
  { taskCode: 'SECURITY_TRAINING', title: 'Assign security awareness training', ownerGroup: 'SECURITY', dueOffset: 7, risk: 'STANDARD' },
  { taskCode: 'MANAGER_PLAN', title: 'Confirm buddy and first-week priorities', ownerGroup: 'HIRING_MANAGER', dueOffset: -3, risk: 'STANDARD' }
];
const tasks = baseline.map((task) => ({
  externalKey: `${record.caseId}:${task.taskCode}`,
  ...task,
  dueAt: due(task.dueOffset),
  status: 'PENDING',
  approvalRequired: task.risk === 'CONTROLLED'
}));
for (const system of record.requestedSystems) {
  const code = String(system).toUpperCase().replace(/[^A-Z0-9]+/g, '_');
  tasks.push({
    externalKey: `${record.caseId}:ACCESS_${code}`,
    taskCode: `ACCESS_${code}`,
    title: `Review access request: ${system}`,
    ownerGroup: 'SYSTEM_OWNER',
    dueAt: due(-1),
    status: 'PENDING_APPROVAL',
    risk: 'CONTROLLED',
    approvalRequired: true
  });
}
return [{ json: { ...record, status: 'TASKS_CREATED', requirements: { equipmentProfile, trainingCodes: ['SECURITY_101', 'PRIVACY_101'] }, tasks, audit: [...record.audit, { event: 'TASK_PLAN_CREATED', at: new Date().toISOString(), actor: 'workflow', taskCount: tasks.length }] } }];

const record = $json;
const firstName = record.employee.fullName.split(/\s+/)[0];
const plan = {
  title: `${firstName}'s first week`,
  generatedBy: 'DETERMINISTIC_PROTOTYPE',
  note: 'In production this structure is generated from the versioned prompt and approved resource catalog.',
  days: [
    { day: 1, focus: 'Welcome, manager alignment, account setup, and orientation' },
    { day: 2, focus: 'Team introductions, role context, and security training' },
    { day: 3, focus: 'Tools, processes, and first guided task' },
    { day: 4, focus: 'Role learning and stakeholder introductions' },
    { day: 5, focus: 'First-week review, feedback, and next-week goals' }
  ]
};
return [{ json: {
  accepted: true,
  caseId: record.caseId,
  correlationId: record.correlationId,
  status: record.status,
  employeeSummary: { fullName: record.employee.fullName, jobTitle: record.employee.jobTitle, department: record.employee.department, location: record.employee.location, startDate: record.employee.startDate },
  requirements: record.requirements,
  tasks: record.tasks,
  onboardingPlan: plan,
  nextActions: ['Persist case with idempotent upsert', 'Create downstream tickets through adapters', 'Request approvals for controlled access', 'Send approved stakeholder communications'],
  audit: [...record.audit, { event: 'ONBOARDING_PLAN_DRAFTED', at: new Date().toISOString(), actor: 'workflow', generator: 'DETERMINISTIC_PROTOTYPE' }]
} }];
